for(int i = 0; i <= 9; ++i)

if (i!=4 && i !=5)

draw((2i,0)--(2i,3));
for(int j = 0; j <= 3; ++j)

draw((0,j)--(18,j));

draw((2*4,0)--(2*4,1));
draw((2*5,0)--(2*5,1));
draw((2*4,2)--(2*4,3));
draw((2*5,2)--(2*5,3));

label("$A$",(0,3),NW);
label("$B$",(18,0),E);
dot("$C$",(8,2),NE);
dot("$D$",(8,1),SE);[/asy]

